  static void Check(bool value,string message){assertions++;if(!value)throw new Exception("FAIL: "+message);}
  static object Call(string name,params object[] args){var m=Api.GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).Single(x=>x.Name==name&&x.GetParameters().Length==args.Length);try{return m.Invoke(null,args);}catch(TargetInvocationException x){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(x.InnerException).Throw();throw;}}
