   foreach(string kind in new[]{"edit","restore"}){var e=AbruptFixture(kind);string world=Path.Combine(e.User,"Saves","Sandbox","中文 世界");Check(!Directory.Exists(world),"abrupt "+kind+" really leaves target absent before recovery");var first=D(Call("EditRecovery",e));var row=RecoveryRows(first).Single();Check(Convert.ToBoolean(first["pending"])&&Convert.ToBoolean(row["supported"])&&(string)row["saveId"]=="Sandbox/中文 世界","reader discovers owned interrupted "+kind+" without creating the missing world");Check(!Directory.Exists(world),"reading pending "+kind+" never changes missing target");Refuses(()=>Call("RecoverEdit",e,row["id"],row["stamp"],false,CancellationToken.None),"interrupted recovery requires confirmation");var result=D(Call("RecoverEdit",e,row["id"],row["stamp"],true,CancellationToken.None));Check((string)result["status"]=="completed"&&File.ReadAllText(Path.Combine(world,"current"))=="before abrupt replacement","explicit recovery restores complete displaced "+kind+" original");Check(!Convert.ToBoolean(D(Call("EditRecovery",e))["pending"]),"recovered "+kind+" no longer reports pending");}
   foreach(string kind in new[]{"edit-published","restore-published"}){var e=AbruptFixture(kind);string world=Path.Combine(e.User,"Saves","Sandbox","中文 世界");var row=RecoveryRows(Call("EditRecovery",e)).Single();Check(Convert.ToBoolean(row["supported"])&&Directory.Exists(world),"published "+kind+" is detected as completed content rather than missing original");string data=File.ReadAllText(Path.Combine(world,"map","楼层","数据.bin"));Call("RecoverEdit",e,row["id"],row["stamp"],true,CancellationToken.None);Check(File.ReadAllText(Path.Combine(world,"map","楼层","数据.bin"))==data&&!Convert.ToBoolean(D(Call("EditRecovery",e))["pending"]),"published "+kind+" cleanup preserves the verified completed save");}
   RecoveryRefusals();
  }
