   var f=new Fixture();byte[] original=File.ReadAllBytes(Path.Combine(f.World,"map","楼层","数据.bin"));string id=(string)D(f.Create())["id"];Check(Guid.ParseExact(id,"N")!=Guid.Empty,"archive id is opaque");var row=f.Archives().Single();Check((string)row["label"]=="手动备份"&&!Convert.ToBoolean(row["automatic"])&&Convert.ToInt32(row["fileCount"])==1,"history has manual label and actual file count");
   using(var zip=ZipFile.OpenRead(f.Zip(id))){Check(zip.GetEntry("manifest.json")!=null&&zip.GetEntry("world/map/楼层/数据.bin")!=null&&zip.GetEntry("world/空目录/")!=null,"archive includes manifest nested Chinese file and empty directory");using(var input=zip.GetEntry("world/map/楼层/数据.bin").Open())using(var bytes=new MemoryStream()){input.CopyTo(bytes);Check(bytes.ToArray().SequenceEqual(original),"ZIP preserves exact binary bytes");}}
   Put(Path.Combine(f.World,"map","楼层","数据.bin"),"changed before restore");Put(Path.Combine(f.World,"new-file"),"displaced save");Refuses(()=>Call("Restore",f.E,f.Id,id,false,CancellationToken.None),"restore requires confirmation");Check(File.Exists(Path.Combine(f.World,"new-file")),"unconfirmed restore preserves current save");var result=D(Call("Restore",f.E,f.Id,id,true,CancellationToken.None));Check(File.ReadAllBytes(Path.Combine(f.World,"map","楼层","数据.bin")).SequenceEqual(original)&&Directory.Exists(Path.Combine(f.World,"空目录"))&&!File.Exists(Path.Combine(f.World,"new-file")),"full restore replaces world with exact original bytes and directories");string recovery=(string)result["recoveryId"];Check(f.Archives().Any(r=>(string)r["id"]==recovery&&Convert.ToBoolean(r["recovery"])),"displaced save is preserved as protected recovery archive");Call("Restore",f.E,f.Id,recovery,true,CancellationToken.None);Check(File.ReadAllText(Path.Combine(f.World,"new-file"))=="displaced save","recovery archive can undo a restore");f.Preserved();Refuses(()=>Call("Delete",f.E,f.Id,id,false),"archive deletion requires confirmation");Call("Delete",f.E,f.Id,id,true);Check(!f.Archives().Any(r=>(string)r["id"]==id),"explicit archive deletion removes only selected opaque archive");Refuses(()=>Call("Delete",f.E,f.Id,"../escape",true),"archive deletion rejects traversal id");
  }
