  static void ProgressAndStageCancellation(){
   // Catches silent scans/verifications and activity callbacks that lose native cancellation.
   var f=new Fixture();string small=Path.Combine(f.World,"map","楼层","数据.bin"),large=Path.Combine(f.World,"payload.bin");File.WriteAllBytes(small,new byte[]{1,3,5,7,9});byte[] bytes=new byte[2097152];new Random(1901).NextBytes(bytes);File.WriteAllBytes(large,bytes);var watch=Stopwatch.StartNew();var events=new List<Tuple<int,string,long>>();f.E.Progress=(value,text)=>events.Add(Tuple.Create(value,text,watch.ElapsedMilliseconds));f.Create();
